<!doctype html><html><head><meta charset="utf-8"><title>Goods Receipt {{ $receipt->number }}</title><style>body{font-family:Arial,sans-serif;color:#12233f;margin:32px}header{display:flex;justify-content:space-between;gap:24px;border-bottom:2px solid #2563eb;padding-bottom:16px}table{border-collapse:collapse;width:100%;margin-top:24px}th,td{border:1px solid #ccd7e5;padding:8px;text-align:left}th{background:#f1f5f9}.muted{color:#64748b}.meta{margin-top:20px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.status{font-weight:700}.total{margin:24px 0 0 auto;max-width:320px;border-top:2px solid #12233f;padding-top:10px;display:flex;justify-content:space-between;font-weight:700}@media print{body{margin:12mm}}</style></head><body><header><div><h1>Goods Receipt {{ $receipt->number }}</h1><p class="muted">{{ $receipt->company?->legal_name ?: $receipt->company?->name ?: 'Company' }} @if($receipt->company?->street_address), {{ $receipt->company->street_address }} @endif</p></div><div class="status">{{ ucfirst($receipt->state) }}<p class="muted">PO: {{ $receipt->purchaseOrder?->number ?: '—' }}</p></div></header><div class="meta"><div><strong>Supplier</strong><br>{{ $receipt->purchaseOrder?->supplier?->name ?: '—' }}</div><div><strong>Receipt date</strong><br>{{ $receipt->receipt_date?->format('Y-m-d') ?: '—' }}</div><div><strong>Warehouse</strong><br>{{ $receipt->warehouse?->name ?: '—' }}</div></div><table><thead><tr><th>Product</th><th>SKU</th><th>Location</th><th>Received</th><th>Accepted</th><th>Rejected</th><th>Damaged</th></tr></thead><tbody>@foreach($receipt->items as $item)<tr><td>{{ $item->purchaseOrderItem?->variant?->product?->name ?: 'Product' }}</td><td>{{ $item->purchaseOrderItem?->variant?->sku ?: '—' }}</td><td>{{ $item->location?->name ?: '—' }}</td><td>{{ $item->quantity }}</td><td>{{ $item->accepted_quantity }}</td><td>{{ $item->rejected_quantity }}</td><td>{{ $item->damaged_quantity }}</td></tr>@endforeach</tbody></table>@if($receipt->receiving_notes)<p><strong>Notes:</strong> {{ $receipt->receiving_notes }}</p>@endif<p class="total"><span>Posting status</span><span>{{ ucfirst($receipt->state) }}</span></p><p class="muted">Draft receipts are not posted to inventory. Posted receipts are immutable and linked to the inventory ledger.</p><script>window.print()</script></body></html>
